/**
 * MA two interior footpoints, A of degree 2 (implicit form coefficients `v`), B cubic:
 * returns `[a, b, e]` with `a[k][i]` (`b[k][i]`) the coefficient of `σ^i` in `aₖ` (`bₖ`)
 * where `f₂^eₖ·Gₖ ≡ aₖ·π + bₖ (mod F)`; with `e = max eₖ`, `a = Σ vₖf₂^(e-eₖ)aₖ` and
 * similarly `b`, the resultant is `(f₂b² - f₁ab + f₀a²)/f₂^e`
 * (27290 terms; multiplications: 594047 without sharing,
 * 39857 with 10002 shared products)
 */
function maiAB_A2B3(bx: number[], by: number[]): [number[][], number[][], number[]] {
    const o = evalProgram2(P, [bx[2], bx[3], by[2], by[3]]);
    const a: number[][] = [];
    const b: number[][] = [];
    let i = 0;
    for (const n of [14, 14, 14, 9, 9, 4]) { a.push(Array.from(o.subarray(i, i += n))); }
    for (const n of [15, 15, 15, 10, 10, 5]) { b.push(Array.from(o.subarray(i, i += n))); }
    return [a, b, [5, 5, 5, 3, 3, 1]];
}


